resource "aws_api_gateway_rest_api" "api" {
  name        = "cg-api-${var.cgid}"
  description = "API for demonstrating leaked API key scenario"
}

resource "aws_api_gateway_resource" "resource" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  parent_id   = aws_api_gateway_rest_api.api.root_resource_id
  path_part   = "user-data"
}

resource "aws_api_gateway_method" "method" {
  rest_api_id      = aws_api_gateway_rest_api.api.id
  resource_id      = aws_api_gateway_resource.resource.id
  http_method      = "GET"
  authorization    = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_integration" "integration" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method
  type        = "MOCK"

  request_templates = {
    "application/json" = jsonencode({
      statusCode = 200
    })
  }
}

resource "aws_api_gateway_method_response" "method_response" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method
  status_code = "200"
}

resource "aws_api_gateway_integration_response" "integration_response" {
  rest_api_id = aws_api_gateway_rest_api.api.id
  resource_id = aws_api_gateway_resource.resource.id
  http_method = aws_api_gateway_method.method.http_method
  status_code = aws_api_gateway_method_response.method_response.status_code
  response_templates = {
    "application/json" = jsonencode({
      message = "Access granted"
      user_data = {
        user_id  = "1337"
        username = "SuperAdmin"
        email    = "SuperAdmin@notarealemail.com"
        password = "p@ssw0rd123"
      }
      final_flag = "FLAG{SNS_S3cr3ts_ar3_FUN}"
    })
  }
}

resource "aws_api_gateway_deployment" "deployment" {
  depends_on = [
    aws_api_gateway_integration.integration,
    aws_api_gateway_integration_response.integration_response
  ]

  rest_api_id = aws_api_gateway_rest_api.api.id
}

resource "aws_api_gateway_stage" "stage" {
  stage_name    = "prod-${var.cgid}"
  rest_api_id   = aws_api_gateway_rest_api.api.id
  deployment_id = aws_api_gateway_deployment.deployment.id
}

resource "aws_api_gateway_usage_plan" "usage_plan" {
  name = "cg-usage-plan-${var.cgid}"

  api_stages {
    api_id = aws_api_gateway_rest_api.api.id
    stage  = aws_api_gateway_stage.stage.stage_name
  }
}

resource "aws_api_gateway_api_key" "api_key" {
  name    = "cg-api-key-${var.cgid}"
  enabled = true
}

resource "aws_api_gateway_usage_plan_key" "usage_plan_key" {
  key_id        = aws_api_gateway_api_key.api_key.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.usage_plan.id
}

# IAM role used by the lambda function to publish to SNS
resource "aws_iam_role" "lambda" {
  name                 = "cg-sns-secrets-${var.cgid}"
  description          = "Allows Lambda to publish to SNS and write logs to CloudWatch"
  max_session_duration = 60 * 60

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  inline_policy {
    name = "writeCloudWatchLogs"
    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Sid    = "writeCloudWatchLogs"
          Effect = "Allow"
          Action = [
            "logs:CreateLogStream",
            "logs:PutLogEvents"
          ]
          Resource = "${aws_cloudwatch_log_group.lambda.arn}:log-stream:*"
        },
        {
          Sid      = "publishSNS"
          Effect   = "Allow"
          Action   = "sns:Publish"
          Resource = aws_sns_topic.public_topic.arn
        }
      ]
    })
  }
}


# IAM User for subscribing to SNS
resource "aws_iam_user" "sns_user" {
  name = "cg-sns-user-${var.cgid}"
}

resource "aws_iam_user_policy" "sns_user_policy" {
  name = "cg-sns-user-policy-${var.cgid}"
  user = aws_iam_user.sns_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sns:Subscribe",
          "sns:Receive",
          "sns:ListSubscriptionsByTopic",
          "sns:ListTopics",
          "sns:GetTopicAttributes",
          "iam:ListGroupsForUser",
          "iam:ListUserPolicies",
          "iam:GetUserPolicy",
          "iam:ListAttachedUserPolicies",
          "apigateway:GET"
        ]
        Resource = "*"
      },
      {
        Effect = "Deny"
        Action = "apigateway:GET"
        Resource = [
          "arn:aws:apigateway:${var.region}::/apikeys",
          "arn:aws:apigateway:${var.region}::/apikeys/*",
          "arn:aws:apigateway:${var.region}::/restapis/*/resources/*/methods/GET",
          "arn:aws:apigateway:${var.region}::/restapis/*/methods/GET",
          "arn:aws:apigateway:${var.region}::/restapis/*/resources/*/integration",
          "arn:aws:apigateway:${var.region}::/restapis/*/integration",
          "arn:aws:apigateway:${var.region}::/restapis/*/resources/*/methods/*/integration"
        ]
      }
    ]
  })
}

resource "aws_iam_access_key" "sns_user_key" {
  user = aws_iam_user.sns_user.name
}

resource "aws_cloudwatch_log_group" "lambda" {
  name              = "/aws/lambda/cg-sns-secrets-${var.cgid}"
  retention_in_days = 1
  skip_destroy      = false
}

resource "aws_lambda_function" "sns_publisher" {
  function_name = "cg-sns-secrets-${var.cgid}"
  description   = "Pubishes API gateway secrets to SNS"
  runtime       = "python3.12"
  package_type  = "Zip"
  role          = aws_iam_role.lambda.arn
  handler       = "lambda.handler"
  memory_size   = 128
  timeout       = 63

  source_code_hash = data.archive_file.lambda_code.output_base64sha256
  filename         = data.archive_file.lambda_code.output_path

  logging_config {
    log_format = "JSON"
    log_group  = aws_cloudwatch_log_group.lambda.name
  }

  environment {
    variables = {
      API_GATEWAY_KEY = aws_api_gateway_api_key.api_key.value
      SNS_ARN         = aws_sns_topic.public_topic.arn
    }
  }
}


resource "aws_cloudwatch_event_rule" "lambda_cron_trigger" {
  name                = "cg-sns-secrets-${var.cgid}"
  description         = "Triggers the CloudGoat sns lambda function every 2 minutes"
  schedule_expression = "rate(2 minutes)"
  state               = "ENABLED"
}

resource "aws_cloudwatch_event_target" "lambda_trigger" {
  arn  = aws_lambda_function.sns_publisher.arn
  rule = aws_cloudwatch_event_rule.lambda_cron_trigger.name
}

resource "aws_lambda_permission" "allow_eventbridge_trigger" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.sns_publisher.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.lambda_cron_trigger.arn
}

output "sns_user_access_key_id" {
  value = aws_iam_access_key.sns_user_key.id
}

output "sns_user_secret_access_key" {
  value     = aws_iam_access_key.sns_user_key.secret
  sensitive = true
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.6.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

# Create SNS Topic
resource "aws_sns_topic" "public_topic" {
  name = "public-topic-${var.cgid}"
}

# SNS Topic Policy to allow public access
resource "aws_sns_topic_policy" "public_topic_policy" {
  arn = aws_sns_topic.public_topic.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action = [
          "sns:Subscribe",
          "sns:Receive",
          "sns:ListSubscriptionsByTopic"
        ]
        Resource = aws_sns_topic.public_topic.arn
      }
    ]
  })
}

variable "profile" {
  description = "The AWS profile to use"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming"
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address(es)"
  type        = list(string)
}

variable "region" {
  description = "The AWS region to deploy to"
  default     = "us-east-1"
  type        = string
}

variable "stack-name" {
  description = "Name of the CloudGoat stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario"
  default     = "iam_privesc_by_key_rotation"
  type        = string
}
